"""Cartões de regra dos temas novos, com a fonte de cada um."""

def TEX(x, verb=False):
    s = "Conferido: Tex's French Grammar (Universidade do Texas em Austin, licença CC BY 3.0), " + x
    if verb:
        s += " As formas verbais foram conferidas pela biblioteca verbecc."
    return s

def WB(x, verb=False, extra=""):
    s = "Conferido: Wikibooks «Italian Grammar» (capítulos que você enviou), " + x
    if verb:
        s += " As formas verbais foram conferidas pela biblioteca verbecc."
    return s + extra

def CGE(x):
    return "Conferido: Cambridge Grammar of English (Carter e McCarthy), PDF que você enviou, " + x

